private async TxtSenha_Enter(provedor: ui.BaseUIElemento, e: ui.UIEventArgs)
{
    if (String.IsNullOrWhiteSpace(this.LoginViewModel.Senha))
    {
        await this.ValidarFormularioAsync();
        return;
    }

    if (String.IsNullOrWhiteSpace(this.LoginViewModel.Email))
    {
        this.TxtEmail.Focus();
    }
    else
    {
        this.EntrarAsync();
    }
}

