private CmbTIpoFace_ValorAlterado(provedor: ui.BaseUIElemento, e: ui.UIValorAlteradoEventArgs)
{
    const tipoFaceSelecionado = e.Valor as EnumTipoFace;

    switch (tipoFaceSelecionado)
    {
        case EnumTipoFace.Lamina:
            this.TipoFaceQuantidade = "Número de lâminas";
            return;
        case EnumTipoFace.Pagina:
            this.TipoFaceQuantidade = "Número de páginas";
            return;
        default:
            throw new Erro("tipo face não suportada");
    }


}

private async BtnControleItemArrastar_Click(controleItemArrastar: ControleItemArrastar, e: ui.UIEventArgs)
{
    const itemViewModel = controleItemArrastar.DataSource;
    if (itemViewModel instanceof ItemViewModel)
    {
        const isContinuar = itemViewModel instanceof FundoViewModel ? true : await controleItemArrastar.IsContinuarAsync();
        if (isContinuar)
        {
            this.ControleMontagem.AdicionarNovoControleItem(itemViewModel, null, true);
        }
    }
}

private async DataLista_LinhaDetalhesExpandida(provedor: ui.BaseUIElemento, e: ui.LinhaDetalhesExpandidaEventArgs)
{
    const precoGrupoEstojo = provedor.DataSource;
    if (precoGrupoEstojo instanceof GrupoTipoEstojoEspessuraViewModel)
    {
        if (!precoGrupoEstojo.IsCarregado)
        {

            const controleDetalhes = e.LinhaDetalhes.RetornarControleFilho(ControleDetalhesPrecoEstojo, true);
            await controleDetalhes.CarregarAsync(precoGrupoEstojo);
            precoGrupoEstojo.IsCarregado = true;
        }
    }
}

public DataLista_OrdenacaoAlterada(dataLista: ui.DataLista, e: ui.OrdenacaoColunaAlteradaEventArgs)
{
    if (e.Parametros?.ContainsKey("Ordenacao"))
    {
        this.Paginacao.Resetar();

        const ordenacao = e.Parametros.Item("Ordenacao");
        const sentido = e.Coluna.SentidoOrdenacao;
        this.Ordenacao = this.RetornarOrdenacao(ordenacao, sentido);
        this.Sentido = this.RetornarSentido(sentido);

        this.AtualizarListaAsync();
    }
}

